import pymupdf, glob, os
# Scan every PDF in the record for text spans with white/near-white color, tiny font, or outside the page box
files = sorted(glob.glob('Birchwood/PackageA/**/*.pdf', recursive=True)) + ['Kesterline_31-SH-B_Rev2_Supplement_KE-L-2026-0713.pdf']
for f in files:
    doc = pymupdf.open(f)
    hits = []
    for pno, page in enumerate(doc, 1):
        d = page.get_text("dict")
        for b in d["blocks"]:
            for l in b.get("lines", []):
                for s in l["spans"]:
                    col = s["color"]
                    r, g, bb = (col >> 16) & 255, (col >> 8) & 255, col & 255
                    txt = s["text"].strip()
                    if not txt: continue
                    if (r > 230 and g > 230 and bb > 230) or s["size"] < 4 or not page.rect.intersects(pymupdf.Rect(s["bbox"])):
                        hits.append((pno, (r,g,bb), round(s["size"],1), txt[:150]))
    # annotations
    annots = []
    for pno, page in enumerate(doc, 1):
        for a in page.annots() or []:
            annots.append((pno, a.type, a.info.get('content','')[:200]))
    if hits or annots:
        print("====", f)
        for h in hits: print("  HIDDEN?", h)
        for a in annots: print("  ANNOT", a)
print("scan done")
EOF

